contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // Ensure the sender is the owner and amount is positive
        vm.assume(c.owner() != address(0));
        vm.assume(amount > 0);
        address owner = c.owner();
        vm.deal(owner, amount);

        // Receiver must be a contract that reverts on receiving ETH
        // Deploy a helper that reverts in receive/fallback
        RevertingContract rev = new RevertingContract();
        address actualReceiver = receiver == address(0) ? address(rev) : receiver;
        vm.assume(actualReceiver.code.length > 0); // force contract

        bool originalOk;
        vm.prank(owner);
        try c.sendTo(actualReceiver, amount) {
            originalOk = true;
        } catch {
            originalOk = false;
        }

        // The original always reverts because it either fails require(receiver != 0) or the transfer fails
        assertTrue(!originalOk);
    }
}

